import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Sprite Themes, 5-State Variants & Base Renderer","description":"","frontmatter":{},"headers":[],"relativePath":"en/1.21.4/ui/index.md","filePath":"en/1.21.4/ui/index.md"}'),a={name:"en/1.21.4/ui/index.md"};function i(s,e,n,c,l,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sprite-themes-5-state-variants-base-renderer" tabindex="-1">Sprite Themes, 5-State Variants &amp; Base Renderer <a class="header-anchor" href="#sprite-themes-5-state-variants-base-renderer" aria-label="Permalink to &quot;Sprite Themes, 5-State Variants &amp; Base Renderer&quot;">​</a></h1><p><code>module.ui</code> provides a flexible widget rendering library (<code>dev.anvilcraft.lib.v2.ui.flexible</code>) not tied to vanilla&#39;s fixed texture dimensions, supporting auto-sizing to text width, light/dark themes, 3D/flat border styles, and complete 5-state mouse interaction variant resolution.</p><h2 id="module-info" tabindex="-1">Module Info <a class="header-anchor" href="#module-info" aria-label="Permalink to &quot;Module Info&quot;">​</a></h2><ul><li>Mod ID: <code>anvillib_ui</code> (<code>AnvilLibUi.MODID</code>)</li><li>Resource path helper: <code>AnvilLibUi.of(String path)</code></li></ul><h2 id="sprite-matrix-dimensions-flexiblesprites" tabindex="-1">Sprite Matrix Dimensions: <code>FlexibleSprites</code> <a class="header-anchor" href="#sprite-matrix-dimensions-flexiblesprites" aria-label="Permalink to &quot;Sprite Matrix Dimensions: `FlexibleSprites`&quot;">​</a></h2><p><code>FlexibleSprites</code> addresses every nine-slice button or flyout background along four orthogonal dimensions:</p><table tabindex="0"><thead><tr><th>Dimension Enum</th><th>Values</th><th>Sprite Naming &amp; Visual Meaning</th></tr></thead><tbody><tr><td><code>SpriteTheme</code></td><td><code>LIGHT(&quot;&quot;)</code>, <code>DARK(&quot;dark&quot;)</code></td><td>Light (no prefix) or dark background theme</td></tr><tr><td><code>SpriteStyle</code></td><td><code>THREE_D(&quot;&quot;)</code>, <code>FLAT(&quot;flat&quot;)</code></td><td>Raised 3D border (no prefix) or modern flat style</td></tr><tr><td><code>SpriteType</code></td><td><code>NON_SHADED</code>, <code>SHADED_1PX</code>, <code>SHADED_2PX</code></td><td>Controls 4-way padding and bottom/top shadow thickness (pressed states shift shadow to the top edge for a depressed feel)</td></tr><tr><td><code>SpriteVariant</code></td><td><code>NORMAL(&quot;&quot;)</code>, <code>HIGHLIGHTED</code>, <code>PRESSED</code>, <code>HIGHLIGHTED_PRESSED</code>, <code>HIGHLIGHTED_PRESSING</code></td><td>5 interaction states: normal, hovered, selected, selected+hovered, hovered+pressing</td></tr></tbody></table><p>Helper static methods &amp; records:</p><ul><li><code>FlexibleSprites.pickSprite(SpriteTheme, SpriteStyle, SpriteType, SpriteVariant)</code>: computes the resolved <code>SpriteInfo(ResourceLocation sprite, int paddingTop, int paddingBottom, ...)</code>.</li><li><code>FlexibleSprites.pickPointer(SpriteTheme, SpriteStyle, SpriteVariant, PointerDirection)</code>: computes the flyout pointer&#39;s <code>PointerSprite(ResourceLocation texture, int width, int height, int pointerUpInset)</code>.</li></ul><h2 id="interaction-state-machine-buttontype-buttoninput" tabindex="-1">Interaction State Machine: <code>ButtonType</code> &amp; <code>ButtonInput</code> <a class="header-anchor" href="#interaction-state-machine-buttontype-buttoninput" aria-label="Permalink to &quot;Interaction State Machine: `ButtonType` &amp; `ButtonInput`&quot;">​</a></h2><p>Instead of manually writing <code>if (hovered &amp;&amp; pressed ...)</code>, specify a <code>ButtonType</code> to map live mouse and boolean toggle states to <code>SpriteVariant</code>:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> record</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ButtonInput</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> toggleState, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> hovered, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pressed, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> startedInBounds) {}</span></span></code></pre></div><table tabindex="0"><thead><tr><th><code>ButtonType</code> Value</th><th>Widget Use Case</th><th>5-State Behavior</th></tr></thead><tbody><tr><td><code>DISPLAY</code></td><td>Display-only panels, tab badges</td><td>Ignores mouse position and press state; always returns <code>NORMAL</code></td></tr><tr><td><code>MOMENTARY</code></td><td>Momentary action buttons</td><td>Returns <code>HIGHLIGHTED</code> on hover, <code>HIGHLIGHTED_PRESSING</code> when pressed from inside the widget</td></tr><tr><td><code>TOGGLE</code></td><td>Persistent toggles / tabs</td><td>Reads <code>toggleState</code> for <code>PRESSED</code> or <code>HIGHLIGHTED_PRESSED</code>, plus <code>HIGHLIGHTED_PRESSING</code> while held</td></tr><tr><td><code>CLICK</code></td><td>Standard click submit buttons</td><td>Combines immediate press and hover feedback during clicks</td></tr></tbody></table><p><code>buttonType.variant(ButtonInput)</code> returns the resolved <code>SpriteVariant</code>.</p><h2 id="abstract-base-renderer-renderer-t-extends-scope-scope" tabindex="-1">Abstract Base Renderer: <code>Renderer&lt;T extends Scope&gt;</code> &amp; <code>Scope</code> <a class="header-anchor" href="#abstract-base-renderer-renderer-t-extends-scope-scope" aria-label="Permalink to &quot;Abstract Base Renderer: `Renderer&lt;T extends Scope&gt;` &amp; `Scope`&quot;">​</a></h2><p><code>Renderer</code> holds invariant appearance config and interaction bindings (reusable across frames in a screen without per-frame allocations); each draw calls <code>renderer.open()</code> to open an <code>AutoCloseable</code> temporary <code>Scope</code>, sets position, font, text, and mouse position, calls <code>.render()</code>, and lets <code>try-with-resources</code> release frame references to <code>GuiGraphics</code> etc.</p><h3 id="renderer-t-configuration-input-forwarding-api" tabindex="-1"><code>Renderer&lt;T&gt;</code> Configuration &amp; Input Forwarding API <a class="header-anchor" href="#renderer-t-configuration-input-forwarding-api" aria-label="Permalink to &quot;`Renderer&lt;T&gt;` Configuration &amp; Input Forwarding API&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>dark()</code></td><td>Switches to dark theme <code>SpriteTheme.DARK</code></td></tr><tr><td><code>flat()</code></td><td>Switches to flat style <code>SpriteStyle.FLAT</code></td></tr><tr><td><code>shaded1px()</code> / <code>shaded2px()</code></td><td>Switches border shadow thickness</td></tr><tr><td><code>highlighted()</code> / <code>pressed()</code> / <code>highlightedPressed()</code> / <code>highlightedPressing()</code></td><td>Locks to a static display variant (overrides dynamic mouse derivation)</td></tr><tr><td><code>buttonType(ButtonType)</code></td><td>Sets <code>ButtonType</code>, independent of <code>basedOnMouse(...)</code> call order</td></tr><tr><td><code>toggleState(BooleanSupplier)</code></td><td>Binds external selected-state supplier for <code>TOGGLE</code> buttons, read each frame</td></tr><tr><td><code>alpha(float alpha)</code></td><td>Sets overall opacity <code>[0.0F, 1.0F]</code> (<code>NaN</code> is ignored, keeping previous value); note that vanilla text shaders discard fragments when text alpha &lt; <code>0.1</code></td></tr><tr><td><code>basedOnMouse()</code> / <code>basedOnMouse(IntSet allowedKeys)</code></td><td>Enables mouse-driven 5-state transitions; no-arg defaults to left and right mouse buttons</td></tr><tr><td><code>onPress(int x, int y)</code> / <code>onPress(Vector2f pos)</code> / <code>onRelease()</code></td><td>Forwards press start position and release in <code>Screen#mouseClicked</code> and <code>#mouseReleased</code> to accurately track whether press started inside</td></tr><tr><td><code>variantOf(T scope)</code></td><td>Queries the final resolved <code>SpriteVariant</code> for the current <code>Scope</code> state</td></tr><tr><td><code>open()</code></td><td>Opens a frame-level render scope <code>T</code></td></tr></tbody></table><h3 id="renderer-scope-common-fluent-methods" tabindex="-1"><code>Renderer.Scope</code> Common Fluent Methods <a class="header-anchor" href="#renderer-scope-common-fluent-methods" aria-label="Permalink to &quot;`Renderer.Scope` Common Fluent Methods&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>graphics(GuiGraphics)</code> / <code>font(Font)</code></td><td>Passes target <code>GuiGraphics</code> and <code>Font</code></td></tr><tr><td><code>pos(int x, int y)</code> / <code>pos(Vector2i)</code></td><td>Sets top-left screen coordinates</td></tr><tr><td><code>mousePos(int x, int y)</code> / <code>mousePos(Vector2f)</code></td><td>Sets current mouse coordinates (required when non-<code>DISPLAY</code> <code>basedOnMouse</code> is enabled)</td></tr><tr><td><code>size(int width, int height)</code> / <code>size(Vector2i)</code></td><td>Sets fixed pixel width and height</td></tr><tr><td><code>flexSize(int padding)</code> / <code>flexSize(hPad, vPad)</code> / <code>flexSize(left, top, right, bottom)</code></td><td>Auto-computes total size from text width and sprite shadow paddings</td></tr><tr><td><code>literal(String)</code> / <code>translatable(String[, args...])</code> / <code>translatableWithFallback(...)</code> / <code>text(Component)</code></td><td>Sets rendered text</td></tr><tr><td><code>textOffset(int, int)</code> / <code>textOffset(Vector2i)</code></td><td>Fine-tunes text render offset</td></tr><tr><td><code>contains(@Nullable Vector2f point)</code></td><td>Hit-tests the widget&#39;s bounding box</td></tr><tr><td><code>render()</code></td><td>Submits sprite background and centered text draw</td></tr><tr><td><code>close()</code></td><td>Releases frame references inside the scope</td></tr></tbody></table>',20)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
